/**
 * Primary Flight Display (PFD) - VFR HUD for WebGCS
 * Renders all 15 required flight instrument components
 * File size: Must stay under 200 lines per WebGCS PRD
 */

class PrimaryFlightDisplay {
    constructor(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.telemetryData = {};
        this.isConnected = false;

        // Set canvas size
        this.canvas.width = 800;
        this.canvas.height = 600;

        // Initialize telemetry listener
        this.initializeTelemetry();

        // Start render loop
        this.render();
    }

    initializeTelemetry() {
        // Listen for telemetry updates
        if (typeof socket !== 'undefined') {
            socket.on('telemetry_stream', (data) => {
                this.telemetryData = data;
                this.isConnected = data.connected;
            });
        }
    }

    render() {
        // Clear canvas
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        if (!this.isConnected) {
            this.drawDisconnectedState();
            requestAnimationFrame(() => this.render());
            return;
        }

        // Draw all VFR HUD components
        this.drawArtificialHorizon();          // #8 - Center artificial horizon
        this.drawAircraftSymbol();             // #9 - Aircraft reference symbol
        this.drawAirspeedTape();              // #1 - Left airspeed indicator
        this.drawAltitudeTape();              // #7 - Right altitude tape
        this.drawHeadingCompass();            // #3 - Heading compass
        this.drawBankAngleIndicator();        // #4 - Bank angle arc
        this.drawFlightModeDisplay();         // #14 - Flight mode
        this.drawArmedStatus();               // #10 - Armed/disarmed overlay
        this.drawBatteryStatus();             // #11 - Battery with color coding
        this.drawGPSStatus();                 // #12 - GPS fix and satellites
        this.drawTelemetryLink();             // #5 - Link quality (top right)
        this.drawGPSTime();                   // #6 - GPS time UTC
        this.drawCrosstrackError();           // #2 - Crosstrack & turn rate
        this.drawSpeedReadouts();             // #15 - Airspeed/groundspeed
        this.drawWaypointDistance();          // #13 - Distance to waypoint

        // Continue render loop
        requestAnimationFrame(() => this.render());
    }

    drawDisconnectedState() {
        this.ctx.fillStyle = '#ff0000';
        this.ctx.font = '24px Arial';
        this.ctx.fillText('DISCONNECTED', this.canvas.width/2 - 80, this.canvas.height/2);
    }

    drawArtificialHorizon() {
        const centerX = this.canvas.width / 2;
        const centerY = this.canvas.height / 2;
        const size = 180;

        const roll = this.telemetryData.roll || 0;
        const pitch = this.telemetryData.pitch || 0;

        this.ctx.save();
        this.ctx.translate(centerX, centerY);
        this.ctx.rotate(roll);

        // Sky (blue)
        this.ctx.fillStyle = '#87CEEB';
        this.ctx.fillRect(-size, -size, size*2, size + pitch*50);

        // Ground (brown)
        this.ctx.fillStyle = '#8B4513';
        this.ctx.fillRect(-size, pitch*50, size*2, size);

        // Horizon line
        this.ctx.strokeStyle = '#FFFFFF';
        this.ctx.lineWidth = 3;
        this.ctx.beginPath();
        this.ctx.moveTo(-size, pitch*50);
        this.ctx.lineTo(size, pitch*50);
        this.ctx.stroke();

        this.ctx.restore();
    }

    drawAircraftSymbol() {
        const centerX = this.canvas.width / 2;
        const centerY = this.canvas.height / 2;

        this.ctx.strokeStyle = '#FFFF00';
        this.ctx.lineWidth = 3;
        this.ctx.beginPath();
        this.ctx.moveTo(centerX - 30, centerY);
        this.ctx.lineTo(centerX + 30, centerY);
        this.ctx.moveTo(centerX, centerY - 15);
        this.ctx.lineTo(centerX, centerY + 15);
        this.ctx.stroke();
    }

    drawAirspeedTape() {
        const x = 50;
        const y = 150;
        const height = 300;
        const airspeed = Math.sqrt(Math.pow(this.telemetryData.groundspeed || 0, 2));

        this.ctx.fillStyle = 'rgba(0,0,0,0.8)';
        this.ctx.fillRect(x-30, y, 60, height);

        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '16px Arial';
        this.ctx.fillText('AS', x-10, y-10);
        this.ctx.fillText(Math.round(airspeed).toString(), x-15, y+height/2);
    }

    drawAltitudeTape() {
        const x = this.canvas.width - 80;
        const y = 150;
        const height = 300;
        const altitude = this.telemetryData.alt || 0;

        this.ctx.fillStyle = 'rgba(0,0,0,0.8)';
        this.ctx.fillRect(x, y, 60, height);

        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '16px Arial';
        this.ctx.fillText('ALT', x+15, y-10);
        this.ctx.fillText(Math.round(altitude).toString(), x+10, y+height/2);
    }

    drawHeadingCompass() {
        const centerX = this.canvas.width / 2;
        const y = 50;
        const heading = this.telemetryData.heading || 0;

        this.ctx.fillStyle = 'rgba(0,0,0,0.8)';
        this.ctx.fillRect(centerX-100, y-20, 200, 40);

        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '18px Arial';
        this.ctx.fillText(`HDG: ${Math.round(heading)}°`, centerX-40, y+5);
    }

    drawBankAngleIndicator() {
        const centerX = this.canvas.width / 2;
        const centerY = this.canvas.height / 2 - 100;
        const radius = 80;
        const roll = this.telemetryData.roll || 0;

        this.ctx.strokeStyle = '#FFFFFF';
        this.ctx.lineWidth = 2;
        this.ctx.beginPath();
        this.ctx.arc(centerX, centerY, radius, Math.PI*0.75, Math.PI*0.25);
        this.ctx.stroke();

        // Bank indicator
        this.ctx.save();
        this.ctx.translate(centerX, centerY);
        this.ctx.rotate(roll);
        this.ctx.fillStyle = '#FFFF00';
        this.ctx.fillRect(-2, -radius, 4, 15);
        this.ctx.restore();
    }

    drawFlightModeDisplay() {
        const mode = this.telemetryData.mode || 'UNKNOWN';
        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '18px Arial';
        this.ctx.fillText(`MODE: ${mode}`, 20, 30);
    }

    drawArmedStatus() {
        const armed = this.telemetryData.armed || false;
        this.ctx.fillStyle = armed ? '#FF0000' : '#00FF00';
        this.ctx.font = '20px Arial';
        this.ctx.fillText(armed ? 'ARMED' : 'DISARMED', this.canvas.width/2 - 40, 30);
    }

    drawBatteryStatus() {
        const voltage = this.telemetryData.battery_voltage || 0;
        const remaining = this.telemetryData.battery_remaining || 0;

        // Color coding: red < 20%, yellow < 50%, green >= 50%
        let color = '#FF0000';
        if (remaining >= 50) color = '#00FF00';
        else if (remaining >= 20) color = '#FFFF00';

        this.ctx.fillStyle = color;
        this.ctx.font = '16px Arial';
        this.ctx.fillText(`BAT: ${voltage.toFixed(1)}V ${remaining}%`, 20, this.canvas.height - 60);
    }

    drawGPSStatus() {
        const fixType = this.telemetryData.gps_fix_type || 0;
        const sats = this.telemetryData.satellites_visible || 0;

        this.ctx.fillStyle = fixType >= 3 ? '#00FF00' : '#FFFF00';
        this.ctx.font = '16px Arial';
        this.ctx.fillText(`GPS: ${sats} SAT`, 20, this.canvas.height - 40);
    }

    drawTelemetryLink() {
        this.ctx.fillStyle = this.isConnected ? '#00FF00' : '#FF0000';
        this.ctx.font = '16px Arial';
        this.ctx.fillText('LINK', this.canvas.width - 60, 30);
    }

    drawGPSTime() {
        const now = new Date();
        const utc = now.toUTCString().split(' ')[4];
        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '16px Arial';
        this.ctx.fillText(`UTC: ${utc}`, this.canvas.width - 120, 50);
    }

    drawCrosstrackError() {
        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '14px Arial';
        this.ctx.fillText('XTK: 0.0', this.canvas.width/2 + 60, 50);
    }

    drawSpeedReadouts() {
        const groundspeed = this.telemetryData.groundspeed || 0;
        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '14px Arial';
        this.ctx.fillText(`GS: ${Math.round(groundspeed)}`, 20, this.canvas.height - 20);
    }

    drawWaypointDistance() {
        this.ctx.fillStyle = '#00FF00';
        this.ctx.font = '14px Arial';
        this.ctx.fillText('WP: --', this.canvas.width - 80, this.canvas.height - 20);
    }
}

// Global PFD instance
let pfd = null;

// Initialize PFD when page loads
document.addEventListener('DOMContentLoaded', function() {
    if (document.getElementById('pfd-canvas')) {
        pfd = new PrimaryFlightDisplay('pfd-canvas');
    }
});

/**
 * Interactive Map for WebGCS
 * Provides real-time drone tracking and click-to-navigate functionality
 * File size: Must stay under 200 lines per WebGCS PRD
 */

class InteractiveMap {
    constructor(mapId) {
        this.mapElement = document.getElementById(mapId);
        this.map = null;
        this.droneMarker = null;
        this.waypointMarkers = [];
        this.telemetryData = {};
        this.isConnected = false;

        // Default map center (can be updated with drone position)
        this.defaultLat = 37.7749;
        this.defaultLon = -122.4194;

        this.initializeMap();
        this.initializeTelemetry();
    }

    initializeMap() {
        // Create Leaflet map
        this.map = L.map(this.mapElement.id).setView([this.defaultLat, this.defaultLon], 15);

        // Add OpenStreetMap tiles (works offline if cached)
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors',
            maxZoom: 19
        }).addTo(this.map);

        // Add map click handler for navigation
        this.map.on('click', (e) => this.handleMapClick(e));

        // Add scale control
        L.control.scale().addTo(this.map);
    }

    initializeTelemetry() {
        // Listen for telemetry updates
        if (typeof socket !== 'undefined') {
            socket.on('telemetry_stream', (data) => {
                this.telemetryData = data;
                this.isConnected = data.connected;
                this.updateDronePosition();
            });
        }
    }

    updateDronePosition() {
        if (!this.isConnected || !this.telemetryData.lat || !this.telemetryData.lon) {
            return;
        }

        const lat = this.telemetryData.lat;
        const lon = this.telemetryData.lon;
        const heading = this.telemetryData.heading || 0;
        const altitude = this.telemetryData.alt || 0;
        const armed = this.telemetryData.armed || false;

        // Create or update drone marker
        if (!this.droneMarker) {
            // Create custom drone icon
            const droneIcon = L.divIcon({
                className: 'drone-marker',
                html: this.createDroneIconHTML(heading, armed),
                iconSize: [30, 30],
                iconAnchor: [15, 15]
            });

            this.droneMarker = L.marker([lat, lon], { icon: droneIcon })
                .addTo(this.map)
                .bindPopup(`
                    <b>Drone Position</b><br>
                    Lat: ${lat.toFixed(6)}<br>
                    Lon: ${lon.toFixed(6)}<br>
                    Alt: ${altitude.toFixed(1)}m<br>
                    Hdg: ${heading.toFixed(1)}°<br>
                    Status: ${armed ? 'ARMED' : 'DISARMED'}
                `);
        } else {
            // Update existing marker
            this.droneMarker.setLatLng([lat, lon]);
            this.droneMarker.setIcon(L.divIcon({
                className: 'drone-marker',
                html: this.createDroneIconHTML(heading, armed),
                iconSize: [30, 30],
                iconAnchor: [15, 15]
            }));

            // Update popup
            this.droneMarker.setPopupContent(`
                <b>Drone Position</b><br>
                Lat: ${lat.toFixed(6)}<br>
                Lon: ${lon.toFixed(6)}<br>
                Alt: ${altitude.toFixed(1)}m<br>
                Hdg: ${heading.toFixed(1)}°<br>
                Status: ${armed ? 'ARMED' : 'DISARMED'}
            `);
        }

        // Auto-center map on first position update
        if (!this.hasInitialPosition) {
            this.map.setView([lat, lon], 17);
            this.hasInitialPosition = true;
        }
    }

    createDroneIconHTML(heading, armed) {
        const color = armed ? '#ff0000' : '#00ff00';
        const transform = `rotate(${heading}deg)`;

        return `
            <div style="
                width: 100%; 
                height: 100%; 
                display: flex; 
                align-items: center; 
                justify-content: center;
                transform: ${transform};
            ">
                <div style="
                    width: 0; 
                    height: 0; 
                    border-left: 10px solid transparent;
                    border-right: 10px solid transparent;
                    border-bottom: 20px solid ${color};
                "></div>
            </div>
        `;
    }

    handleMapClick(e) {
        const lat = e.latlng.lat;
        const lon = e.latlng.lng;

        // Create temporary waypoint marker
        const waypointMarker = L.marker([lat, lon])
            .addTo(this.map)
            .bindPopup(`
                <b>Waypoint</b><br>
                Lat: ${lat.toFixed(6)}<br>
                Lon: ${lon.toFixed(6)}<br>
                <button onclick="window.mapInstance.navigateToWaypoint(${lat}, ${lon})">Go To</button>
                <button onclick="window.mapInstance.removeWaypoint(this)">Remove</button>
            `)
            .openPopup();

        this.waypointMarkers.push(waypointMarker);

        // Auto-populate navigation fields if they exist
        this.populateNavigationFields(lat, lon);
    }

    populateNavigationFields(lat, lon) {
        const latField = document.getElementById('nav-lat');
        const lonField = document.getElementById('nav-lon');

        if (latField && lonField) {
            latField.value = lat.toFixed(6);
            lonField.value = lon.toFixed(6);
        }
    }

    navigateToWaypoint(lat, lon) {
        // Send navigation command via existing navigation system
        if (typeof socket !== 'undefined') {
            const altitude = document.getElementById('nav-alt')?.value || 10;

            // Use the existing navigation button click handler
            const gotoBtn = document.getElementById('goto-btn');
            if (gotoBtn) {
                // Populate fields and trigger navigation
                this.populateNavigationFields(lat, lon);
                gotoBtn.click();
            }
        }
    }

    removeWaypoint(markerReference) {
        // Find and remove the marker (simplified approach)
        this.waypointMarkers.forEach((marker, index) => {
            if (marker.getPopup().getElement().contains(markerReference)) {
                this.map.removeLayer(marker);
                this.waypointMarkers.splice(index, 1);
            }
        });
    }

    clearAllWaypoints() {
        this.waypointMarkers.forEach(marker => {
            this.map.removeLayer(marker);
        });
        this.waypointMarkers = [];
    }

    centerOnDrone() {
        if (this.droneMarker) {
            const pos = this.droneMarker.getLatLng();
            this.map.setView([pos.lat, pos.lng], 17);
        }
    }

    setMapStyle(style) {
        // Allow switching between map styles
        const styles = {
            'street': 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
            'satellite': 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
            'terrain': 'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png'
        };

        if (styles[style]) {
            // Remove existing tile layer and add new one
            this.map.eachLayer(layer => {
                if (layer instanceof L.TileLayer) {
                    this.map.removeLayer(layer);
                }
            });

            L.tileLayer(styles[style], {
                attribution: '© Map providers',
                maxZoom: 19
            }).addTo(this.map);
        }
    }

    getMapInfo() {
        return {
            center: this.map.getCenter(),
            zoom: this.map.getZoom(),
            dronePosition: this.droneMarker ? this.droneMarker.getLatLng() : null,
            waypointCount: this.waypointMarkers.length,
            connected: this.isConnected
        };
    }
}

